import React from 'react';
const { useEffect, useState } = wp.element;
const BackgroundVideoControls = ({ videoID }) => {
    const [video, setVideo] = useState(null);
    useEffect(() => {
        setVideo(videoID ? document.getElementById(videoID) : null);
    }, []);
    if (video) {
        const controlsID = 'do-controls-' + videoID;
        video.removeAttribute('controls');
        // Add event listeners
        //video.addEventListener( 'ended', onended );
        const playPauseOnclick = (e) => {
            const playPauseButton = e.target;
            if (video.paused) {
                video.play();
                playPauseButton.classList.remove('play');
                playPauseButton.classList.add('pause');
                playPauseButton.innerHTML = '<span>Pause</span>';
            }
            else {
                video.pause();
                playPauseButton.classList.remove('pause');
                playPauseButton.classList.add('play');
                playPauseButton.innerHTML = '<span>Play</span>';
            }
        };
        const rewindOnclick = (e) => {
            video.currentTime -= 3;
        };
        const forwardOnclick = (e) => {
            video.currentTime += 3;
        };
        // const onended = ( e ) => {
        //     const playPauseButton = '';
        //     playPauseButton.classList.remove( 'pause' );
        //     playPauseButton.classList.add( 'play' );
        //     playPauseButton.innerHTML = '<span>Play</span>';
        // }
        return (React.createElement("div", { className: "do-controls-wrapper", id: controlsID + '-wrapper' },
            React.createElement("button", { className: "do-control rewind", id: controlsID + '-rewind', onClick: (e) => rewindOnclick },
                React.createElement("span", null, "Rewind")),
            React.createElement("button", { className: "do-control pause", id: controlsID + '-playpause', onClick: (e) => playPauseOnclick },
                React.createElement("span", null, "Pause")),
            React.createElement("button", { className: "do-control forward", id: controlsID + '-forward', onClick: (e) => forwardOnclick },
                React.createElement("span", null, "Forward"))));
    }
    else {
        return null;
    }
};
export default BackgroundVideoControls;
